from typing import Dict, Any

def get_family_drama_masterpiece_story(title: str = '') -> Dict[str, Any]:
    story_title = title if title else "Đêm Mưa Bị Đuổi Khỏi Hào Môn: Màn Lật Kèo Đòi Lại Căn Biệt Thự 50 Tỷ"
    part1_full = "Bảy năm sau đêm mưa bị đuổi ra khỏi cổng nhà chồng với chiếc vali rách, tôi trở lại buổi đấu giá bất động sản trung tâm với tư cách chủ tịch quỹ đầu tư nắm giữ căn biệt thự năm mươi tỷ.\n\nNhững ánh mắt ngỡ ngàng đổ dồn về phía người phụ nữ mặc bộ âu phục lụa đen quý phái, trên cổ đeo sợi dây chuyền kim cương giọt lệ xanh lam trị giá triệu đô la. Đó là Tô Nhược Dao – người con dâu nghèo hèn từng bị cả gia tộc họ Hoàng sỉ nhục bảy năm trước! Ngồi đối diện với cô là bà Mai – người mẹ chồng từng một thời hét ra lửa, nay gương mặt tái mét, toàn thân run rẩy như chiếc lá úa trước gió.\n\nKý ức của bảy năm tủi nhục bỗng chốc ùa về như một cơn bão tuyết cào xé tâm can. Bảy năm trước, Nhược Dao bước chân vào gia đình hào môn với danh nghĩa người vợ xuất thân từ vùng quê nghèo. Vì tình yêu mù quáng với Hoàng Minh Triết – cậu ấm duy nhất của tập đoàn dệt may Hoàng Gia – cô đã từ bỏ sự nghiệp học hành để toàn tâm toàn ý chăm sóc cho gia đình chồng. Thế nhưng, sự hy sinh nhẫn nhục của cô chỉ đổi lại sự khinh miệt đến tận xương tủy từ người mẹ chồng cay nghiệt.\n\nMỗi sáng sớm từ bốn giờ rưỡi, khi sương mù còn giăng kín khuôn viên căn biệt thự năm mươi tỷ ven sông, Nhược Dao đã phải thức dậy chuẩn bị bữa sáng cho cả gia đình. Bát yến chưng nếu quá ngọt một chút sẽ bị bà Mai hắt thẳng vào người. Chiếc áo sơ mi lụa của cô em chồng nếu ủi phẳng phiu nhưng có một nếp nhăn nhỏ nơi cổ áo sẽ bị xé toạc ngay trước mặt người làm. Nhược Dao cắn răng chịu đựng tất cả, chỉ vì đứa con gái nhỏ bé đang lớn lên từng ngày trong bụng.\n\nThế nhưng đỉnh điểm của bi kịch ập đến vào một đêm giông bão kinh hoàng cấp mười hai. Cô em chồng Hoàng Kiều My bị vỡ nợ chứng khoán năm tỷ đồng, đã lén lấy trộm chuỗi ngọc trai gia bảo của gia tộc đem đi cầm cố. Để thoát tội, hai mẹ con bà Mai đã cấu kết với nhau vu oan giá họa cho Nhược Dao. Ngay trong bữa cơm tối, bà Mai tát thẳng vào mặt cô một cú trời giáng, lớn tiếng sỉ nhục cô là 'thứ tiện tì ăn cắp, nuôi ong tay áo'!\n\nDù Nhược Dao có quỳ gối khóc cạn nước mắt thề thốt sự trong sạch, dù cô con gái nhỏ ba tuổi khóc thét ôm lấy chân bà nội van xin, bà Mai vẫn lạnh lùng sai người làm ném toàn bộ quần áo của hai mẹ con ra cổng sắt. Giữa cơn mưa bão xối xả ngập bùn đất, người chồng từng hứa hẹn bảo bọc cô trọn đời – Hoàng Minh Triết – chỉ đứng lạnh lùng sau khung cửa kính hút thuốc lá, buông một câu tàn nhẫn: 'Ký vào đơn ly hôn và biến đi, đồ đàn bà nghèo hèn xúi quẩy!'. Đứng dưới cơn mưa bão lạnh buốt, Nhược Dao ôm chặt đứa con thơ đang sốt cao bốn mươi độ trong lòng, đôi mắt cô rực lên ngọn lửa thù hận không bao giờ tắt. Nhưng ngay lúc cô tưởng chừng như sắp ngã quỵ, một chiếc Rolls-Royce đen bóng bỗng phanh gấp trước mặt...\n\nNỗi đau đớn thể xác không bao giờ có thể sánh bằng sự vụn vỡ của một trái tim từng trao trọn niềm tin cho kẻ bội bạc. Dưới cơn mưa đêm tầm tã năm ấy, từng giọt nước lạnh buốt như ngàn mũi kim châm vào da thịt người mẹ trẻ đơn độc. Nhược Dao siết chặt mảnh giấy ghi lại số điện thoại cứu trợ khẩn cấp, từng bước chân lảo đảo trên con đường sình lầy ngoại thành. Cô tự thề với chính linh hồn mình rằng sẽ có một ngày, cô quay trở lại căn biệt thự này với một vị thế hoàn toàn khác. Kẻ gieo gió nhất định sẽ phải gặt bão, và sự kiên cường của một người mẹ bảo vệ con sẽ là vũ khí sắc bén nhất đập tan mọi sự ngạo mạn của hào môn!"
    part2_full = "Chiếc xe sedan màu đen dừng trước sảnh tòa nhà tập đoàn Hoàng Thị, khi tôi cùng đội ngũ luật sư bước vào phòng họp cổ đông để công bố hồ sơ kiểm toán độc lập. Đó chính là Cố Vạn Toàn – Chủ tịch sáng lập tập đoàn tài chính Đông Á lừng danh khắp châu Á! Và bí mật chấn động suốt hai mươi năm qua được hé lộ: Nhược Dao chính là người con gái thất lạc của ông sau vụ tai nạn chìm tàu năm xưa!\n\nBảy năm sau đêm mưa bão định mệnh ấy, Nhược Dao đã hoàn toàn lột xác. Dưới sự huấn luyện khắt khe của cha ruột, cô tiếp quản vị trí Tổng giám đốc điều hành quỹ đầu tư Đông Á, nắm giữ huyết mạch kinh tế của hàng trăm doanh nghiệp lớn nhỏ. Trong khi đó, gia tộc họ Hoàng vì thói làm ăn chộp giật, cờ bạc và đầu tư bất động sản thua lỗ đã rơi vào cảnh nợ nần chồng chất hơn một trăm tỷ đồng!\n\nCăn biệt thự năm mươi tỷ – biểu tượng danh vọng duy nhất còn lại của nhà họ Hoàng – bị ngân hàng phát mãi đấu giá công khai. Bà Mai và Minh Triết chạy vạy khắp nơi, cố gắng dùng những đồng tiền cuối cùng để tìm kiếm một nhà đầu tư cứu vãn sản nghiệp. Nhưng tại phiên đấu giá nghẹt thở, mỗi lần Hoàng Minh Triết giơ biển trả giá, một giọng nói nữ thanh thoát, lạnh lùng từ hàng ghế VIP lại giơ biển nâng giá lên gấp đôi!\n\nKhi mức giá chạm ngưỡng một trăm hai mươi tỷ đồng, Hoàng Minh Triết quay lại nhìn về phía hàng ghế VIP với ánh mắt căm phẫn tột độ. Nhưng khi chiếc rèm che nhung đỏ từ từ vén lên, hắn và bà Mai chết lặng như bị bàng hoàng! Người phụ nữ đang nắm trong tay quyền sinh sát cả gia tộc họ Hoàng chính là người vợ nghèo bị họ đuổi ra đường trong đêm mưa bão bảy năm trước! Nhược Dao nhếch mép cười, giơ cao chiếc búa đấu giá: 'Căn biệt thự này, từ nay thuộc về tôi!'.\n\nThương trường như chiến trường, nơi mà kẻ yếu đuối sẽ bị nuốt chửng không thương tiếc bởi những toan tính lạnh lùng. Bảy năm tôi luyện nơi đầu sóng ngọn gió đã biến cô gái thôn quê nhút nhát ngày nào thành một nữ vương quyền lực trên thương trường quốc tế. Từng đường đi nước bước trong chiến lược thâu tóm tập đoàn Hoàng Gia đều được Nhược Dao tính toán chuẩn xác đến từng xu lẻ. Bà Mai đứng trên bục đấu giá, đôi bàn tay gầy guộc bấu chặt vào lan can gỗ, miệng lắp bắp không nói nên lời trước sự thật tàn nhẫn. Sự kiêu ngạo của một gia tộc phù phiếm bỗng chốc vỡ tan tành như bong bóng xà phòng dưới ánh sáng của thực lực và công lý!"
    part3_full = "Buổi bàn giao quyền sở hữu căn biệt thự năm mươi tỷ diễn ra ngay dưới ánh nắng sớm, khép lại hoàn toàn chuỗi ngày bất công của bảy năm về trước. Bà Mai và Hoàng Minh Triết quỳ gối dưới chân cô, van xin được giữ lại một gian phòng nhỏ để sống qua ngày. Người đàn ông từng bội bạc năm xưa gục đầu khóc lóc, thề thốt hối hận và cầu xin Nhược Dao vì đứa con mà quay lại hàn gắn hôn nhân.\n\nNhược Dao nhìn xuống hai kẻ hèn hạ ấy bằng ánh mắt lạnh lùng như băng tuyết. Cô rút từ túi xách ra tập hồ sơ khám nghiệm tài chính năm xưa, vạch trần toàn bộ thủ đoạn chiếm đoạt di chúc và hành vi trốn thuế của tập đoàn Hoàng Gia. 'Bảy năm trước các người tàn nhẫn đuổi mẹ con tôi đi, hôm nay pháp luật sẽ dạy cho các người bài học về nhân quả!'. Tiếng còi xe cảnh sát kinh tế vang lên rền rĩ trước cổng biệt thự.\n\nBà Mai ngất lịm khi chiếc còng số tám bập vào tay con trai vì tội danh lừa đảo tài chính và trốn thuế. Căn biệt thự năm mươi tỷ được Nhược Dao cải tạo thành một trung tâm bảo trợ xã hội dành cho những người phụ nữ và trẻ em bị bạo hành gia đình. Đứng trên ban công nhìn ánh bình minh rạng rỡ soi bóng xuống dòng sông, Nhược Dao mỉm cười thanh thản, tay nắm chặt bàn tay nhỏ nhắn của con gái yêu.\n\nPhụ nữ sinh ra không phải để cam chịu và nhẫn nhục trước sự tàn nhẫn của kẻ khác. Khi bạn đủ bản lĩnh và tự chủ, không một ai có thể xem thường bạn! Nếu bạn là Nhược Dao trong câu chuyện này, liệu bạn có tha thứ cho người chồng bội bạc vì đứa con nhỏ, hay bạn sẽ kiên quyết trừng trị như cô ấy? Hãy để lại bình luận chia sẻ quan điểm của bạn ngay dưới video này nhé!\n\nBình minh rực rỡ ló rạng nơi chân trời, xua tan đi màn sương mù u ám của những năm tháng tủi hờn và cay đắng. Những giọt nước mắt rơi xuống hôm nay không còn là nước mắt của sự bất lực, mà là giọt nước mắt của sự tự do và kiêu hãnh. Một cánh cửa cũ khép lại để mở ra một tương lai tươi sáng ngập tràn hy vọng cho hai mẹ con kiên cường. Giá trị của một con người không bao giờ nằm ở việc họ xuất thân giàu hay nghèo, mà nằm ở bản lĩnh đứng dậy sau mỗi lần vấp ngã. Và công lý của cuộc đời luôn là một thước đo công bằng nhất: gieo nhân nào thì nhất định sẽ gặt quả nấy!"
    return {
        'title': story_title,
        'genre': "GIA_DAU",
        'voice': "vi-VN-HoaiMyNeural",
        'bgm_genre': "ROMANCE",
        'parts': [
            {'part_number': 1, 'badge_label': 'TẬP 1', 'title': f'[TẬP 1] {story_title}', 'text': part1_full, 'full_text': part1_full, 'body': part1_full},
            {'part_number': 2, 'badge_label': 'TẬP 2', 'title': f'[TẬP 2] {story_title}', 'text': part2_full, 'full_text': part2_full, 'body': part2_full},
            {'part_number': 3, 'badge_label': 'TẬP 3 - KẾT', 'title': f'[TẬP 3 - KẾT] {story_title}', 'text': part3_full, 'full_text': part3_full, 'body': part3_full},
        ]
    }
